practiceProblems.solutionCode:
public class Main {
    public static void main(String[] args) {
        int scored = 455;
        int total = 500;
        double percentage = ((double) scored / total) * 100;
        int roundedPercentage = (int) percentage;
        System.out.println("Score: " + scored + "/" + total + " | Exact: " + percentage + "% | Grade Cutoff: " + roundedPercentage);
    }
}

public class Main {
    public static void main(String[] args) {
        int marks = 95;
        double decimalMarks = marks;
        System.out.println("Int: " + marks + " -> Widened Double: " + decimalMarks);
    }
}

public class Main {
    public static void main(String[] args) {
        double cgpa = 8.92;
        int cgpaWhole = (int) cgpa;
        System.out.println("Original CGPA: " + cgpa + " -> Truncated Int: " + cgpaWhole);
    }
}

public class Main {
    public static void main(String[] args) {
        char letter = 'Z';
        int ascii = letter;
        System.out.println("Character: " + letter + " | ASCII Code: " + ascii);
    }
}

public class Main {
    public static void main(String[] args) {
        int val = 130;
        byte b = (byte) val;
        System.out.println("Original Int: " + val + " -> Cast Byte: " + b);
    }
}
